if (root/'recipes.json').exists():
    recipes=json.loads((root/'recipes.json').read_text())
else:
    (root/'recipes.json').write_text(json.dumps(recipes,ensure_ascii=False,indent=2))
cards=[]
recipe_count=len(recipes)
for r in recipes:
    ingredients=''.join('<li>'+html.escape(x)+'</li>' for x in r['ingredients'])
    steps=''.join('<li>'+html.escape(x)+'</li>' for x in r['steps'])
    search=html.escape(' '.join([r['title'],r['category'],r.get('collection','Original selections'),*r['ingredients']]).lower(),quote=True)
    cards.append(f'''<article data-search="{search}" data-category="{html.escape(r['category'])}" data-collection="{html.escape(r.get('collection','Original selections'))}" id="{r['id']}"><p class="eyebrow">{r['category']} · {r.get('collection','Original selections')}</p><h2>{html.escape(r['title'])}</h2><p class="yield">{html.escape(r['yield_text'])}</p><details><summary>Ingredients & instructions</summary><h3>Ingredients</h3><ul>{ingredients}</ul><h3>Method</h3>{'<ol>'+steps+'</ol>' if steps else '<p>Method awaiting completion.</p>'}<p class="note">{html.escape(r['notes'])}</p><h3>Nutrition</h3><p>{html.escape(r['nutrition'])}</p></details></article>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A growing collection of favorite home recipes."><title>My Recipe Book</title><style>
:root{--ink:#23372e;--paper:#faf7ef;--green:#315c47;--line:#d9dfd3}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.6 system-ui,sans-serif}header,main,footer{max-width:1080px;margin:auto;padding:32px 24px}header{padding-top:65px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:2px;color:var(--green);font-weight:700}h1{font:clamp(40px,7vw,72px)/1.1 Georgia,serif;margin:12px 0}h2{font:29px/1.2 Georgia,serif;margin:8px 0}h3{font-size:17px;margin-bottom:8px}.intro{max-width:650px;color:#526358}.tools{display:flex;gap:12px;flex-wrap:wrap;margin:26px 0}label{font-size:14px;display:flex;flex-direction:column;gap:6px;flex:1;min-width:180px}input,select,button{font:inherit;border:1px solid #9aa99b;border-radius:8px;padding:12px;background:white;color:var(--ink)}button{cursor:pointer;align-self:end;background:var(--green);color:white}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}article{border:1px solid var(--line);border-radius:15px;padding:25px;background:#fffdf8;align-self:start}.yield{font-size:14px;color:#526358}summary{cursor:pointer;font-weight:600;color:var(--green);padding:10px 0}li{margin-bottom:7px}.note{background:#eff2e9;border-left:3px solid #8c9d77;padding:12px;font-size:14px}footer{font-size:13px;color:#526358}a{color:var(--green)}[hidden]{display:none!important}@media(max-width:680px){.grid{grid-template-columns:1fr}header{padding-top:32px}}@media print{.tools,#count,footer{display:none}.grid{display:block}article{break-inside:avoid;margin:15px 0}header{padding-top:0}body{background:white}}
</style></head><body><header><p class="eyebrow">The home collection · Volume 01</p><h1>My Recipe Book</h1><p class="intro">Favorite recipes, kept together. Find a recipe by name or ingredient, open its instructions, and make it your own.</p><div class="tools"><label>Search recipes<input id="search" type="search" placeholder="Try carrot, chicken or lime…"></label><label>Category<select id="category"><option value="">All recipes</option><option>Mains</option><option>Salads</option><option>Breads & breakfast</option><option>Sauces & dressings</option></select></label><label>Collection<select id="collection"><option value="">All collections</option><option>Original selections</option><option>Recipes on rotation</option></select></label><button id="print" type="button">Print recipe book</button></div><p id="count" role="status" aria-live="polite">7 recipes</p></header><main><div class="grid">'''+''.join(cards)+'''</div><p id="empty" hidden>No recipes match. Try another ingredient or choose All recipes.</p></main><footer>Collected November 4, 2026. Recorded quantities take priority. Missing original details are marked; earlier nutrition estimates are unverified. Google Doc companion: not connected yet.</footer><script>
const search=document.getElementById('search'),category=document.getElementById('category'),collection=document.getElementById('collection'),cards=[...document.querySelectorAll('article')];function filter(){const terms=search.value.toLowerCase().trim().split(/\\s+/).filter(Boolean);let n=0;for(const card of cards){card.hidden=!(terms.every(t=>card.dataset.search.includes(t))&&(!category.value||card.dataset.category===category.value)&&(!collection.value||card.dataset.collection===collection.value));if(!card.hidden)n++}document.getElementById('count').textContent=n+' recipe'+(n===1?'':'s');document.getElementById('empty').hidden=n!==0}search.addEventListener('input',filter);category.addEventListener('change',filter);collection.addEventListener('change',filter);document.getElementById('print').addEventListener('click',()=>{document.querySelectorAll('details').forEach(d=>d.open=true);window.print()});
</script></body></html>'''
